#!/usr/bin/env python3
"""Write ``fixed_forms_v1.warrant``, the synthetic ``ir.fixed`` document of slice S10a.

The document exercises **every one of the 35 built-ins of VER04r Appendix A.1 at every width
the spec allows**, so that the committed lowering dump (``fixed_forms_v1.oracle-lowering.json``)
pins the IR shape, the typing and the cost of each, and the Rust generator (slice S10b) has one
document to reproduce byte for byte.

It is generated, not hand-written, because the matrix is large: eight fixed-width types, and
the conversions are source x target.  The file is committed next to the dump; a test
(``tests/test_fixed_forms.py``) regenerates it and fails if this script and the committed text
disagree, so the two cannot drift.

    python3 make_fixed_forms.py            # (re)write fixed_forms_v1.warrant
    python3 make_fixed_forms.py --check    # fail if the committed file differs

Only the standard library is used.  Names: ``m_<built-in>_<type>`` for a model of one
built-in at one width (``m_rotl_u32``), ``op_*`` for subject ops, ``c_*`` for claims.
"""

from __future__ import annotations

import pathlib
import sys

HERE = pathlib.Path(__file__).resolve().parent
OUT = HERE / "fixed_forms_v1.warrant"

#: name, bits, signed
TYPES = [
    ("U8", 8, False),
    ("U16", 16, False),
    ("U32", 32, False),
    ("U64", 64, False),
    ("I8", 8, True),
    ("I16", 16, True),
    ("I32", 32, True),
    ("I64", 64, True),
]
BITS = {n: b for n, b, _ in TYPES}
SIGNED = {n: s for n, _, s in TYPES}


def lo_hi(name: str) -> tuple[int, int]:
    b = BITS[name]
    return (-(1 << (b - 1)), (1 << (b - 1)) - 1) if SIGNED[name] else (0, (1 << b) - 1)


def inside(src: str, dst: str) -> bool:
    return lo_hi(dst)[0] <= lo_hi(src)[0] and lo_hi(src)[1] <= lo_hi(dst)[1]


def lit(name: str, value: int) -> str:
    """A suffixed literal of fixed type ``name`` (a negative one is a unary minus)."""
    suffix = name.lower()
    return f"-{-value}{suffix}" if value < 0 else f"{value}{suffix}"


def zero(name: str) -> str:
    return f"0{name.lower()}"


def one(name: str) -> str:
    return f"1{name.lower()}"


def main() -> str:
    out: list[str] = []
    w = out.append
    w("warrant fixed_forms v1")
    w("  -- Synthetic ir.fixed document of slice S10a (VER04r Appendix A.1): every built-in at")
    w("  -- every width the spec allows.  GENERATED by make_fixed_forms.py; do not edit by hand.")
    w("  error FixedError = Bad | Worse")
    w("")
    w("  -- bit operations (WX-C): T, T -> T and T, Nat -> T, per width --------------------------")
    for t, _, signed in TYPES:
        s = t.lower()
        w(f"  model m_bit_and_{s}(a: {t}, b: {t}) -> {t} = bit_and(a, b)")
        w(f"  model m_bit_or_{s}(a: {t}, b: {t}) -> {t} = bit_or(a, b)")
        w(f"  model m_bit_xor_{s}(a: {t}, b: {t}) -> {t} = bit_xor(a, b)")
        w(f"  model m_bit_not_{s}(a: {t}) -> {t} = bit_not(a)")
        w(f"  model m_shl_{s}(a: {t}, n: Nat) -> {t} = shl(a, n)")
        w(f"  model m_shr_{s}(a: {t}, n: Nat) -> {t} = shr(a, n)")
        if signed:
            w(f"  model m_sar_{s}(a: {t}, n: Nat) -> {t} = sar(a, n)")
        w(f"  model m_rotl_{s}(a: {t}, n: Nat) -> {t} = rotl(a, n)")
        w(f"  model m_rotr_{s}(a: {t}, n: Nat) -> {t} = rotr(a, n)")
        w(f"  model m_popcount_{s}(a: {t}) -> Nat = popcount(a)")
        w(f"  model m_clz_{s}(a: {t}) -> Nat = clz(a)")
        w(f"  model m_ctz_{s}(a: {t}) -> Nat = ctz(a)")
        w(f"  model m_bit_{s}(a: {t}, i: Nat) -> Bool = bit(a, i)")
        # literal operands: a suffixed literal takes the operand's type, a bare count is a Nat.
        w(f"  model m_lit_mask_{s}(a: {t}) -> {t} = bit_and(a, {one(t)})")
        w(f"  model m_lit_shift_{s}(a: {t}) -> {t} = shl(a, 3)")
        w(f"  model m_lit_bit_{s}(a: {t}) -> Bool = bit(a, {BITS[t] - 1})")
    w("")
    w("  -- bounds, to_int / to_nat -----------------------------------------------------------")
    for t, _, signed in TYPES:
        s = t.lower()
        w(f"  model m_max_value_{s}() -> {t} = max_value<{t}>()")
        w(f"  model m_min_value_{s}() -> {t} = min_value<{t}>()")
        w(f"  model m_to_int_{s}(a: {t}) -> Int = to_int(a)")
        if not signed:
            w(f"  model m_to_nat_{s}(a: {t}) -> Nat = to_nat(a)")
    w("  model m_wrap_around(a: U8) -> U8 = wrap<U8>(to_int(max_value<U8>()) + 1)")
    w("")
    w("  -- conversions: widen (range inside the target), wrap and try (source x target) ------")
    for src, _, _ in TYPES:
        for dst, _, _ in TYPES:
            if inside(src, dst):
                w(f"  model m_widen_{src.lower()}_{dst.lower()}(a: {src}) -> {dst} = widen<{dst}>(a)")
    for dst, _, _ in TYPES:
        d = dst.lower()
        for src, _, _ in TYPES:
            s = src.lower()
            w(f"  model m_wrap_{s}_{d}(a: {src}) -> {dst} = wrap<{dst}>(a)")
            w(
                f"  model m_try_{s}_{d}(a: {src}) -> {dst} = unwrap_or(try<{dst}>(a), {zero(dst)})"
            )
        for src in ("Int", "Nat"):
            w(f"  model m_wrap_{src.lower()}_{d}(a: {src}) -> {dst} = wrap<{dst}>(a)")
            w(
                f"  model m_try_{src.lower()}_{d}(a: {src}) -> {dst} = unwrap_or(try<{dst}>(a), {zero(dst)})"
            )
    w("")
    w("  -- checked arithmetic (Option<T>, consumed by unwrap_or) -----------------------------")
    for t, _, _ in TYPES:
        s = t.lower()
        for op in ("add", "sub", "mul"):
            w(
                f"  model m_checked_{op}_{s}(a: {t}, b: {t}) -> {t} = "
                f"unwrap_or(checked_{op}(a, b), {zero(t)})"
            )
    w("")
    w("  -- div / rem: unsigned pairs (Option<U>), Int/Nat pairs (Option<Int>, R7) -------------")
    for t, _, signed in TYPES:
        if not signed:
            s = t.lower()
            for op in ("div", "rem"):
                w(f"  model m_{op}_{s}(a: {t}, b: {t}) -> {t} = unwrap_or({op}(a, b), {zero(t)})")
    for op in ("div", "rem"):
        for ta in ("Nat", "Int"):
            for tb in ("Nat", "Int"):
                w(
                    f"  model m_{op}_{ta.lower()}_{tb.lower()}(a: {ta}, b: {tb}) -> Int = "
                    f"unwrap_or({op}(a, b), 0)"
                )
    w("  model m_div_literals() -> Int = unwrap_or(div(7, 2), 0)")
    w("  model m_rem_nat_literal(a: Nat) -> Int = unwrap_or(rem(a, 3), 0)")
    w("")
    w("  -- div_trunc / rem_trunc (signed pairs only, toward zero) -----------------------------")
    for t, _, signed in TYPES:
        if signed:
            s = t.lower()
            for op in ("div_trunc", "rem_trunc"):
                w(f"  model m_{op}_{s}(a: {t}, b: {t}) -> {t} = unwrap_or({op}(a, b), {zero(t)})")
    w("")
    w("  -- imin / imax (Int and Nat operands) ----------------------------------------------")
    for op in ("imin", "imax"):
        for ta in ("Nat", "Int"):
            for tb in ("Nat", "Int"):
                w(f"  model m_{op}_{ta.lower()}_{tb.lower()}(a: {ta}, b: {tb}) -> Int = {op}(a, b)")
    w("")
    w("  -- endian conversions: be_bytes / le_bytes and from_be / from_le -------------------")
    for t, bits, _ in TYPES:
        s = t.lower()
        n = bits // 8
        w(f"  model m_be_bytes_{s}(a: {t}) -> Bytes<{n}> = be_bytes(a)")
        w(f"  model m_le_bytes_{s}(a: {t}) -> Bytes<{n}> = le_bytes(a)")
        w(f"  model m_from_be_{s}(b: Bytes<{n}>) -> {t} = from_be<{t}>(b)")
        w(f"  model m_from_le_{s}(b: Bytes<{n}>) -> {t} = from_le<{t}>(b)")
    w('  model m_from_be_literal() -> U16 = from_be<U16>(b"0102")')
    w('  model m_from_le_concat(t: Bytes<1>) -> U32 = from_le<U32>(concat(t, b"000000"))')
    w("  model m_round_trip_u32(a: U32) -> U32 = from_be<U32>(be_bytes(a))")
    w("")
    w("  -- at: Bytes and Bytes<N>, a Nat or an Int index -------------------------------------")
    w("  model m_at_nat(b: Bytes, i: Nat) -> U8 = unwrap_or(at(b, i), 0u8)")
    w("  model m_at_int(b: Bytes, i: Int) -> U8 = unwrap_or(at(b, i), 255u8)")
    w("  model m_at_fixed(b: Bytes<4>, i: Nat) -> U8 = unwrap_or(at(b, i), 0u8)")
    w("  model m_at_literal_index(b: Bytes) -> U8 = unwrap_or(at(b, 0), 0u8)")
    w("")
    w("  -- compositions: the call closure (R9), nesting, and unwrap_or's default -------------")
    w("  model m_mix_u32(a: U32, b: U32) -> U32 = bit_xor(rotl(a, 5), shr(b, 3))")
    w("  model m_use_rotl(a: U32) -> U32 = m_rotl_u32(a, 7)")
    w("  model m_use_use(a: U32) -> U32 = m_use_rotl(m_mix_u32(a, a))")
    w("  model m_pure_core(a: U8) -> U8 = a + 1u8")
    w("  model m_to_core(a: U8) -> U8 = m_pure_core(a)")
    w("  model m_saturating_sub(a: U8, b: U8) -> U8 = unwrap_or(checked_sub(a, b), 0u8)")
    w("  model m_default_from_model(a: U8, b: U8) -> U8 = unwrap_or(div(a, b), m_pure_core(a))")
    w("  model m_if_fixed(a: U8) -> U8 = if bit(a, 0) then bit_not(a) else a")
    w("  model m_signed_min(a: I8) -> Bool = a == -128i8 or a == min_value<I8>()")
    w("")
    w("  -- subject ops, claims and examples ---------------------------------------------------")
    for t, bits, _signed in TYPES:
        s = t.lower()
        w(f"  op op_and_{s}(a: {t}, b: {t}) -> {t}")
        w(f"  op op_not_{s}(a: {t}) -> {t}")
        w(f"  op op_shl_{s}(a: {t}, n: Nat | n < {2 * bits}) -> {t}")
        w(f"  op op_pop_{s}(a: {t}) -> Nat")
    w("  op op_low_u8(a: U8 | bit_and(a, 128u8) == 0u8) -> U8")
    w("  op op_be32(a: U32) -> Bytes<4>")
    w("  op op_div_u8(a: U8, b: U8) -> U8")
    w("")
    for t, bits, _signed in TYPES:
        s = t.lower()
        w(f"  claim c_and_{s}:")
        w(f"    forall a: {t}, b: {t}. op_and_{s}(a, b) == bit_and(a, b)")
        w(f"  claim c_not_{s}:")
        w(f"    forall a: {t}. op_not_{s}(a) == bit_xor(a, max_value<{t}>()) or op_not_{s}(a) == bit_not(a)")
        w(f"  claim c_shl_{s}:")
        w(f"    forall a: {t}, n: Nat | n < {2 * bits}. op_shl_{s}(a, n) == shl(a, n)")
        w(f"  claim c_pop_{s}:")
        w(f"    forall a: {t}. op_pop_{s}(a) == popcount(a)")
        w(f"  claim c_pop_bound_{s}:")
        w(f"    forall a: {t}. op_pop_{s}(a) <= {bits}")
    w("  claim c_low_u8:")
    w("    forall a: U8 | bit_and(a, 128u8) == 0u8. op_low_u8(a) == m_to_core(a)")
    w("  claim c_be32:")
    w("    forall a: U32. op_be32(a) == be_bytes(a)")
    w("  claim c_be32_round_trip:")
    w("    forall a: U32. from_be<U32>(op_be32(a)) == a")
    w("  claim c_div_u8:")
    w("    forall a: U8, b: U8 | b != 0u8. op_div_u8(a, b) == unwrap_or(div(a, b), 0u8)")
    w("  claim c_closure_only:")
    w("    forall a: U32. op_not_u32(a) == m_use_use(a)")
    w("  claim c_core_only:")
    w("    forall a: U8. op_not_u8(a) == m_pure_core(a)")
    w("")
    w("  example e_rotl: op_not_u8(1u8) == rotl(128u8, 9)")
    w("  example e_widen: op_pop_u16(3u16) == to_nat(widen<U16>(2u8))")
    w("  example e_max: op_not_i8(0i8) == max_value<I8>()")
    w("  example e_core: op_not_u8(1u8) == 254u8")
    w("  example e_unwrap: op_div_u8(7u8, 2u8) == unwrap_or(div(7u8, 2u8), 0u8)")
    w("")
    return "\n".join(out) + "\n"


def run(argv: list[str]) -> int:
    text = main()
    if "--check" in argv:
        if not OUT.exists() or OUT.read_bytes() != text.encode("utf-8"):
            print(f"DIFFERS: {OUT.name}", file=sys.stderr)
            return 1
        print(f"ok: {OUT.name}")
        return 0
    OUT.write_bytes(text.encode("utf-8"))
    print(f"wrote {OUT.name} ({len(text)} bytes)")
    return 0


if __name__ == "__main__":
    raise SystemExit(run(sys.argv[1:]))
